<template><div class="art-full-height page"><ArtSearchBar v-model="filters" :items="[{label:'手机号',key:'phone',type:'input',props:{placeholder:'请输入手机号'}},{label:'姓名',key:'name',type:'input',props:{placeholder:'请输入姓名'}},{label:'身份证号',key:'idCard',type:'input',props:{placeholder:'请输入身份证号'}}]" :show-expand="false" @search="load" @reset="reset"/><ElCard class="art-table-card"><ArtTableHeader :loading="loading" @refresh="load"/><ElTable v-loading="loading" :data="rows"><ElTableColumn type="index" label="序号"/><ElTableColumn prop="id" label="用户ID"/><ElTableColumn prop="phone" label="手机号"/><ElTableColumn prop="name" label="姓名"/><ElTableColumn prop="id_card" label="身份证号" min-width="180"/><ElTableColumn label="身份证正面" width="120"><template #default="{row}"><ElImage v-if="row.id_card_front" :src="row.id_card_front" fit="cover" style="width:70px;height:48px"/><span v-else>未上传</span></template></ElTableColumn><ElTableColumn label="身份证背面" width="120"><template #default="{row}"><ElImage v-if="row.id_card_back" :src="row.id_card_back" fit="cover" style="width:70px;height:48px"/><span v-else>未上传</span></template></ElTableColumn><ElTableColumn label="认证视频"><template #default="{row}">{{row.verification_video?'已上传':'未上传'}}</template></ElTableColumn><ElTableColumn label="认证状态"><template #default="{row}"><ElTag :type="row.verified===1?'success':'info'">{{row.verified===1?'已认证':'未认证'}}</ElTag></template></ElTableColumn></ElTable></ElCard></div></template>
<script setup lang="ts">import{fetchCustomers,type Customer}from'@/api/system-manage';defineOptions({name:'UserVerification'});const loading=ref(false),rows=ref<Customer[]>([]),filters=reactive({phone:'',name:'',idCard:''});const load=async()=>{loading.value=true;try{const data=await fetchCustomers({page:1,pageSize:100,...filters});rows.value=data.records}finally{loading.value=false}};const reset=()=>{Object.assign(filters,{phone:'',name:'',idCard:''});load()};onMounted(load)</script><style scoped>.page{display:flex;flex-direction:column;gap:12px}.art-table-card{flex:1}</style>